gameActivityImportAdditions.insert:
import android.util.Log;
import android.Manifest.permission;
import android.net.wifi.WifiManager;
import android.net.wifi.WifiInfo;

gameActivityClassAdditions.insert:

			private final static String TAG = "ApexSDKAndroid: ";

            public boolean AndroidThunkJava_Launch(String packageName, String extraKey, String extraValue)
			{
				Log.debug(TAG + " AndroidThunkJava_Launch");
				Intent intent;
				String intentAction = "";
				String intentComponent = "";

				int intentActionIndex = packageName.indexOf(":");
				if (intentActionIndex >= 0)
				{
					intentAction = packageName.substring(intentActionIndex + 1);
					packageName = packageName.substring(0, intentActionIndex);

					intentActionIndex = intentAction.indexOf(":");
					if (intentActionIndex >= 0)
					{
						intentComponent = intentAction.substring(intentActionIndex + 1);
						intentAction = intentAction.substring(0, intentActionIndex);
					}
				}

				if (!AndroidThunkJava_IsPackageInstalled(packageName))
				{
					return false;
				}

				if (intentAction.equals(""))
				{
					Log.debug(TAG + "Does not have intent!");

					intent = getPackageManager().getLaunchIntentForPackage(packageName);
					if (intent == null)
					{
						return false;
					}
				}
				else
				{
					Log.debug(TAG + "Has intent!");
					intent = new Intent(intentAction);
					if (intent == null)
					{
						return false;
					}
					intent.setPackage(packageName);
					intent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
				}

				if (!extraKey.equals(""))
				{
					Log.debug(TAG + extraKey + " - " + extraValue);
					intent.putExtra(extraKey, extraValue);
				}

				if (!intentComponent.equals(""))
				{
					intent.setComponent(new android.content.ComponentName(packageName, intentComponent));
				}

				if (intent.resolveActivity(getPackageManager()) != null)
				{
					startActivity(intent);
					AndroidThunkJava_ForceQuit();
					return true;
				}

				return false;
			}

            public String AndroidThunkJava_GetApplicationExtra(String InExtraName)
            {
				Log.debug(TAG + "AndroidThunkJava_GetApplicationExtra: " + InExtraName);
				Intent AppIntent = getIntent();
                Bundle AppExtras = AppIntent.getExtras();

                String ExtraString = "";

                if (AppExtras != null)
                {
					Log.debug(TAG + "Getting extras.");
					ExtraString = AppExtras.getString(InExtraName);
                    Log.debug(TAG + "Got extra as: " + ExtraString);
				}

                return ExtraString;
            }

            public String AndroidThunkJava_GetDeviceSerialNumber()
            {
				Log.error("GAOCA: Getting device serial number.");
				return android.os.Build.getSerial();
            }

            public String AndroidThunkJava_GetMacAddress()
            {
				Log.error("GAOCA: Getting mac address.");
				WifiManager wifiManager = (WifiManager) getApplicationContext().getSystemService(Context.WIFI_SERVICE);
				WifiInfo wInfo = wifiManager.getConnectionInfo();
				String macAddress = wInfo.getMacAddress();
                return macAddress;
            }

